[.tooling/components/apis/ai-gov-review-service/docs/deployment.md#key-terraform-variables]

### Key Terraform Variables

```hcl
variable "environment" {
  description = "Environment name (dev, test, prod)"
  type        = string
}

variable "aws_region" {
  description = "AWS region for deployment"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID for resource deployment"
  type        = string
}

variable "private_subnet_ids" {
  description = "Private subnet IDs for ECS tasks and ElastiCache"
  type        = list(string)
}

variable "public_subnet_ids" {
  description = "Public subnet IDs for ALB"
  type        = list(string)
}

variable "ecs_task_cpu" {
  description = "CPU units for ECS task (1024 = 1 vCPU)"
  type        = number
  default     = 2048
}

variable "ecs_task_memory" {
  description = "Memory for ECS task in MB"
  type        = number
  default     = 4096
}

variable "ecs_service_desired_count" {
  description = "Desired number of ECS tasks"
  type        = number
  default     = 2
}

variable "redis_node_type" {
  description = "ElastiCache Redis node type"
  type        = string
  default     = "cache.t3.small"
}

variable "enable_multi_az" {
  description = "Enable Multi-AZ for ElastiCache"
  type        = bool
  default     = true
}

variable "bedrock_model_id" {
  description = "Bedrock model identifier"
  type        = string
  default     = "anthropic.claude-3-5-sonnet-20240620-v1:0"
}
```

