[.tooling/components/apis/ai-gov-review-service/docs/deployment.md#reviews-table]

#### Reviews Table

```bash
aws dynamodb create-table \
  --table-name governance-reviews \
  --attribute-definitions \
    AttributeName=review_id,AttributeType=S \
    AttributeName=submitter_email,AttributeType=S \
    AttributeName=review_type,AttributeType=S \
    AttributeName=created_at,AttributeType=S \
  --key-schema AttributeName=review_id,KeyType=HASH \
  --billing-mode PAY_PER_REQUEST \
  --global-secondary-indexes \
    '[
      {
        "IndexName": "submitter_email-index",
        "KeySchema": [{"AttributeName":"submitter_email","KeyType":"HASH"}],
        "Projection": {"ProjectionType":"ALL"}
      },
      {
        "IndexName": "review_type-created_at-index",
        "KeySchema": [
          {"AttributeName":"review_type","KeyType":"HASH"},
          {"AttributeName":"created_at","KeyType":"RANGE"}
        ],
        "Projection": {"ProjectionType":"ALL"}
      }
    ]' \
  --region us-east-1
```

