[.tooling/components/apis/ai-gov-review-service/docs/deployment.md#step-4-load-initial-templates]

### Step 4: Load Initial Templates

Create `arb-template.json`:

```json
{
  "template_id": {"S": "arb"},
  "name": {"S": "Architecture Review Board"},
  "version": {"S": "1.0.0"},
  "required_sections": {
    "L": [
      {"S": "Executive Summary"},
      {"S": "Business Context"},
      {"S": "Architecture Overview"},
      {"S": "Technical Design"},
      {"S": "Security Considerations"},
      {"S": "Operations & Support"}
    ]
  },
  "evaluation_criteria": {
    "M": {
      "completeness": {
        "M": {
          "description": {"S": "All required sections present with sufficient detail"},
          "weight": {"N": "0.3"}
        }
      },
      "clarity": {
        "M": {
          "description": {"S": "Clear, well-structured, easy to understand"},
          "weight": {"N": "0.25"}
        }
      },
      "technical_depth": {
        "M": {
          "description": {"S": "Sufficient technical detail for architecture decisions"},
          "weight": {"N": "0.25"}
        }
      },
      "compliance": {
        "M": {
          "description": {"S": "Adheres to enterprise standards and policies"},
          "weight": {"N": "0.2"}
        }
      }
    }
  },
  "scoring_config": {
    "M": {
      "pass_threshold": {"N": "70"},
      "dimension_weights": {
        "M": {
          "completeness": {"N": "0.3"},
          "clarity": {"N": "0.25"},
          "technical_depth": {"N": "0.25"},
          "compliance": {"N": "0.2"}
        }
      }
    }
  },
  "active": {"BOOL": true}
}
```

Load template:

```bash
aws dynamodb put-item \
  --table-name governance-templates \
  --item file://arb-template.json \
  --region us-east-1
```

Repeat for other review types (CRB, DRB, SRB, etc.)

